class Solution:
    def kIncreasing(self, arr: List[int], k: int) -> int:
        import bisect
        def min_ops(sub):
            # longest non-decreasing subsequence
            tails = []
            for x in sub:
                pos = bisect.bisect_right(tails, x)
                if pos == len(tails):
                    tails.append(x)
                else:
                    tails[pos] = x
            return len(sub) - len(tails)
        res = 0
        for start in range(k):
            group = [arr[i] for i in range(start, len(arr), k)]
            res += min_ops(group)
        return res

