class Solution:
    def getDistances(self, arr: List[int]) -> List[int]:
        from collections import defaultdict
        groups = defaultdict(list)
        for i, v in enumerate(arr):
            groups[v].append(i)
        res = [0] * len(arr)
        for indices in groups.values():
            n = len(indices)
            prefix = [0] * (n + 1)
            for i in range(n):
                prefix[i+1] = prefix[i] + indices[i]
            for i in range(n):
                left_sum = indices[i] * i - prefix[i]
                right_sum = (prefix[n] - prefix[i+1]) - indices[i] * (n - 1 - i)
                res[indices[i]] = left_sum + right_sum
        return res

class Solution:
    def recoverArray(self, nums: List[int]) -> List[int]:
        from collections import Counter
        nums.sort()
        n = len(nums) // 2
        for j in range(1, len(nums)):
            diff = nums[j] - nums[0]
            if diff == 0 or diff % 2 != 0:
                continue
            k = diff // 2
            cnt = Counter(nums)
            res = []
            valid = True
            for x in nums:
                if cnt[x] == 0:
                    continue
                if cnt[x + 2*k] == 0:
                    valid = False
                    break
                cnt[x] -= 1
                cnt[x + 2*k] -= 1
                res.append(x + k)
            if valid and len(res) == n:
                return res
        return []

class Solution:
    def minimumOperations(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        match = {}
        def dfs(u, visited):
            for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                ni, nj = u[0]+dx, u[1]+dy
                v = (ni, nj)
                if 0<=ni<m and 0<=nj<n and grid[ni][nj]==1 and v not in visited:
                    visited.add(v)
                    if v not in match or dfs(match[v], visited):
                        match[v] = u
                        return True
            return False
        res = 0
