class Solution:
    def longestPalindrome(self, words: List[str]) -> int:
        from collections import Counter
        cnt = Counter(words)
        res = 0
        has_center = False
        for word in list(cnt.keys()):
            rev = word[::-1]
            if word == rev:
                pairs = cnt[word] // 2
                res += pairs * 4
                if cnt[word] % 2 == 1:
                    has_center = True
            elif rev in cnt:
                pairs = min(cnt[word], cnt[rev])
                res += pairs * 4
                cnt[word] -= pairs
                cnt[rev] -= pairs
        if has_center:
            res += 2
        return res

class Solution:
    def possibleToStamp(self, grid: List[List[int]], stampHeight: int, stampWidth: int) -> bool:
        m, n = len(grid), len(grid[0])
        # prefix sum of grid
        psum = [[0]*(n+1) for _ in range(m+1)]
        for i in range(m):
            for j in range(n):
                psum[i+1][j+1] = psum[i][j+1]+psum[i+1][j]-psum[i][j]+grid[i][j]
        def area_sum(r1,c1,r2,c2):
            return psum[r2+1][c2+1]-psum[r1][c2+1]-psum[r2+1][c1]+psum[r1][c1]
        # 2D difference array for stamp placements
        diff = [[0]*(n+2) for _ in range(m+2)]
        for i in range(m-stampHeight+1):
            for j in range(n-stampWidth+1):
                if area_sum(i,j,i+stampHeight-1,j+stampWidth-1)==0:
                    diff[i][j] += 1
                    diff[i][j+stampWidth] -= 1
                    diff[i+stampHeight][j] -= 1
                    diff[i+stampHeight][j+stampWidth] += 1
        # compute prefix sum of diff
        for i in range(m):
            for j in range(n):
                diff[i][j+1] += diff[i][j]
        for j in range(n):
            for i in range(m):
                diff[i+1][j] += diff[i][j]
        # but we need 2D prefix sum of diff
        # recompute
        cover = [[0]*(n) for _ in range(m)]
        for i in range(m):
            for j in range(n):
                cover[i][j] = diff[i][j]
                if i > 0: cover[i][j] += cover[i-1][j]
                if j > 0: cover[i][j] += cover[i][j-1]
                if i > 0 and j > 0: cover[i][j] -= cover[i-1][j-1]
        # Actually diff already needs 2D prefix to recover
        # Let me redo with proper 2D diff
        # Simpler: recompute from diff directly
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 0 and diff[i][j] == 0:
                    return False
        return True

