class Solution:
    def minSwaps(self, nums: List[int]) -> int:
        k = sum(nums)
        if k == 0:
            return 0
        n = len(nums)
        zeros = sum(1 for i in range(k) if nums[i] == 0)
        min_zeros = zeros
        for i in range(1, n):
            if nums[i-1] == 0:
                zeros -= 1
            if nums[(i+k-1) % n] == 0:
                zeros += 1
            min_zeros = min(min_zeros, zeros)
        return min_zeros

class Solution:
    def wordCount(self, startWords: List[str], targetWords: List[str]) -> int:
        start_masks = set()
        for w in startWords:
            mask = 0
            for c in w:
                mask |= 1 << (ord(c) - ord('a'))
            start_masks.add(mask)
        res = 0
        for w in targetWords:
            mask = 0
            for c in w:
                mask |= 1 << (ord(c) - ord('a'))
            for c in w:
                bit = 1 << (ord(c) - ord('a'))
                if (mask ^ bit) in start_masks:
                    res += 1
                    break
        return res

