class Solution:
    def equalizeWater(self, buckets: List[int], loss: int) -> float:
        lo, hi = 0, max(buckets)
        for _ in range(100):
            mid = (lo + hi) / 2
            pour_out = sum(max(b - mid, 0) * (1 - loss/100) for b in buckets)
            need = sum(max(mid - b, 0) for b in buckets)
            if pour_out >= need:
                lo = mid
            else:
                hi = mid
        return lo

