    def maximumGood(self, statements: List[List[int]]) -> int:
        n = len(statements)
        res = 0
        for mask in range(1, 1 << n):
            valid = True
            for i in range(n):
                if not (mask >> i & 1):
                    continue
                for j in range(n):
                    if statements[i][j] == 0 and (mask >> j & 1):
                        valid = False
                        break
