        par = list(range(n))
        sz = [1]*n
        def find2(x):
            while par[x] != x:
                par[x] = par[par[x]]
                x = par[x]
            return x
        def union2(x, y):
            px, py = find2(x), find2(y)
            if px == py: return
            if sz[px] < sz[py]: px, py = py, px
            par[py] = px
            sz[px] += sz[py]
        from collections import defaultdict
        mask_to_idx = defaultdict(list)
        word_masks = []
        for i, w in enumerate(words):
            mask = 0
            for c in w:
                mask |= 1 << (ord(c)-ord('a'))
            word_masks.append(mask)
            mask_to_idx[mask].append(i)
        # union same masks
        for indices in mask_to_idx.values():
            for i in range(1, len(indices)):
                union2(indices[0], indices[i])
        # union by delete one bit
        del_map = {}
        for mask, indices in mask_to_idx.items():
            rep = indices[0]
            for bit in range(26):
                if mask >> bit & 1:
                    new_mask = mask ^ (1 << bit)
                    if new_mask in mask_to_idx:
                        union2(rep, mask_to_idx[new_mask][0])
                    if new_mask in del_map:
                        union2(rep, del_map[new_mask])
                    else:
                        del_map[new_mask] = rep
        groups = set()
        max_size = 0
        for i in range(n):
            r = find2(i)
            groups.add(r)
            max_size = max(max_size, sz[r])
        return [len(groups), max_size]

from sortedcontainers import SortedList
class Solution:
    def amountPainted(self, paint: List[List[int]]) -> List[int]:
        # Use a set to track painted positions (for small ranges) or interval merge
        painted = [0] * 50001  # jump array
        res = []
        for start, end in paint:
            count = 0
            i = start
            while i < end:
                if painted[i] == 0:
                    count += 1
                    painted[i] = end
                    i += 1
                else:
                    jump = painted[i]
                    painted[i] = max(painted[i], end)
                    i = jump
            res.append(count)
        return res

class Solution:
    def minimumSum(self, num: int) -> int:
        digits = sorted(str(num))
        return int(digits[0]+digits[2]) + int(digits[1]+digits[3])
